-- Generated by n8n/build/quiz_demo.py; explicit demonstration only.
WITH saved_events AS (
      INSERT INTO events (event_id, kind, title, planned_for, status, group_id, owner_staff_id, posted_on, views, shares, source, nps_score)
      SELECT event_id, kind, title, planned_for, status, group_id, owner_staff_id, posted_on, views, shares, source, nps_score FROM json_populate_recordset(NULL::events, $1::json->'events')
      ON CONFLICT (event_id) DO UPDATE SET kind = EXCLUDED.kind, title = EXCLUDED.title, planned_for = EXCLUDED.planned_for, status = CASE WHEN events.status IN ('held','cancelled') AND EXCLUDED.status='planned' THEN events.status ELSE EXCLUDED.status END, group_id = EXCLUDED.group_id, owner_staff_id = EXCLUDED.owner_staff_id, posted_on = EXCLUDED.posted_on, views = EXCLUDED.views, shares = EXCLUDED.shares, source = EXCLUDED.source, nps_score = EXCLUDED.nps_score
      WHERE events.kind='quiz'
      RETURNING event_id
    ), saved_attempts AS (
      INSERT INTO quiz_attempts (event_id, student_id, started_at, completed_at, score, total_questions)
      SELECT a.event_id, a.student_id, a.started_at, a.completed_at, a.score, a.total_questions
      FROM json_populate_recordset(NULL::quiz_attempts, $1::json->'attempts') a
      JOIN saved_events e ON e.event_id=a.event_id
      WHERE EXISTS (SELECT 1 FROM students s WHERE s.student_id=a.student_id)
      ON CONFLICT (event_id,student_id) DO UPDATE SET completed_at = COALESCE(EXCLUDED.completed_at, quiz_attempts.completed_at), score = COALESCE(EXCLUDED.score, quiz_attempts.score), total_questions = COALESCE(EXCLUDED.total_questions, quiz_attempts.total_questions)
      WHERE quiz_attempts.started_at=EXCLUDED.started_at
        AND (quiz_attempts.completed_at IS NULL OR (EXCLUDED.completed_at = quiz_attempts.completed_at
             AND EXCLUDED.score IS NOT DISTINCT FROM quiz_attempts.score
             AND EXCLUDED.total_questions IS NOT DISTINCT FROM quiz_attempts.total_questions))
      RETURNING 1
    ) SELECT (SELECT count(*)::int FROM saved_events) AS events_upserted,
             (SELECT count(*)::int FROM saved_attempts) AS attempts_upserted;
